---

edits.find:
export function validateMrrInputs(existingMrr: number): string | null {
  if (existingMrr < 0) return "Existing MRR cannot be negative.";
  return null;
}

edits.replace:
export function validateMrrInputs(existingMrr: number, lang: "en" | "es" = "en"): string | null {
  if (existingMrr < 0) return lang === "es" ? "El MRR existente no puede ser negativo." : "Existing MRR cannot be negative.";
  return null;
}

edits.find:
  setSubtitle("totalMrrResult", result.netNewMrr >= 0 ? "Growing" : "Shrinking");

  lastSummary = `
MRR Summary

Total MRR: ${fmtCurrency(result.totalMrr)}
Net New MRR: ${fmtCurrency(result.netNewMrr)}
Projected ARR: ${fmtCurrency(result.arr)}
Churned + Contraction MRR: ${fmtCurrency(result.churnedMrr + result.contractionMrr)}
`.trim();

edits.replace:
  setSubtitle("totalMrrResult", result.netNewMrr >= 0 ? (lang === "es" ? "Creciendo" : "Growing") : (lang === "es" ? "Disminuyendo" : "Shrinking"));

  lastSummary = lang === "es" ? `
Resumen de MRR

MRR Total: ${fmtCurrency(result.totalMrr)}
MRR Neto Nuevo: ${fmtCurrency(result.netNewMrr)}
ARR Proyectado: ${fmtCurrency(result.arr)}
MRR Perdido + Contracción: ${fmtCurrency(result.churnedMrr + result.contractionMrr)}
`.trim() : `
MRR Summary

Total MRR: ${fmtCurrency(result.totalMrr)}
Net New MRR: ${fmtCurrency(result.netNewMrr)}
Projected ARR: ${fmtCurrency(result.arr)}
Churned + Contraction MRR: ${fmtCurrency(result.churnedMrr + result.contractionMrr)}
`.trim();
